<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import promptAuditAPI from '@shared-prompt-audit/api'
import type { PromptAuditDraft, PromptAuditEndpointDraft, PromptAuditEvent, PromptAuditGroup, PromptAuditRuntime, PromptDeletePreview, PromptEventFilters, PromptProbeResult } from '@shared-prompt-audit/types'
import { SCANNER_CATALOG, buildUpdateRequest, cloneData, configToDraft, createDefaultEndpoint, draftFingerprint, emptyEventFilters, resolveDeleteRangeFilters } from '@shared-prompt-audit/viewModel'
import ConsoleShell from '@/components/layout/ConsoleShell.vue'
import PageState from '@/components/base/PageState.vue'
import SurfaceDialog from '@/components/base/SurfaceDialog.vue'
import { DialogWidth } from '@/components/base/dialog'
import { ConfirmTone, useConfirmStore } from '@/stores/confirm'
import { useAppStore } from '@/stores/app'
import { PromptAuditTab, PromptDeleteRange, formatCompactNumber, formatDuration, formatGovernanceDate } from '@/features/admin/governance/model'

const app = useAppStore()
const confirm = useConfirmStore()
const activeTab = ref(PromptAuditTab.EVENTS)
const serverDraft = ref<PromptAuditDraft | null>(null)
const draft = ref<PromptAuditDraft | null>(null)
const runtime = ref<PromptAuditRuntime | null>(null)
const groups = ref<PromptAuditGroup[]>([])
const events = ref<PromptAuditEvent[]>([])
const total = ref(0)
const page = ref(1)
const pageSize = ref(20)
const loading = ref(true)
const secondaryLoading = ref(false)
const error = ref('')
const filters = ref<PromptEventFilters>(emptyEventFilters())
const appliedFilters = ref<PromptEventFilters>(emptyEventFilters())
const selected = ref<number[]>([])
const detailOpen = ref(false)
const detail = ref<PromptAuditEvent | null>(null)
const probeResults = ref<Record<string, PromptProbeResult>>({})
const probingIds = ref<string[]>([])
const saving = ref(false)
const deleteByFilterOpen = ref(false)
const deleteRange = ref(PromptDeleteRange.SEVEN_DAYS)
const deletePreview = ref<PromptDeletePreview | null>(null)
const deletePreviewFilters = ref<PromptEventFilters | null>(null)
const deleting = ref(false)

const pages = computed(() => Math.max(1, Math.ceil(total.value / pageSize.value)))
const dirty = computed(() => draftFingerprint(draft.value) !== draftFingerprint(serverDraft.value))
const selectedAll = computed(() => events.value.length > 0 && events.value.every((item) => selected.value.includes(item.id)))

async function loadInitial(): Promise<void> {
  loading.value = true; error.value = ''
  const results = await Promise.allSettled([promptAuditAPI.getConfig(), promptAuditAPI.getRuntime(), promptAuditAPI.listGroups(), promptAuditAPI.listEvents(appliedFilters.value, page.value, pageSize.value)])
  if (results[0].status === 'fulfilled') { serverDraft.value = configToDraft(results[0].value); draft.value = configToDraft(results[0].value) } else error.value = (results[0].reason as { message?: string }).message || '提示词审计配置加载失败'
  if (results[1].status === 'fulfilled') runtime.value = results[1].value
  if (results[2].status === 'fulfilled') groups.value = results[2].value
  if (results[3].status === 'fulfilled') { events.value = results[3].value.items || []; total.value = results[3].value.total || 0 }
  loading.value = false
}

async function loadRuntime(): Promise<void> { secondaryLoading.value = true; try { runtime.value = await promptAuditAPI.getRuntime() } catch (caught) { app.showError((caught as { message?: string }).message || '运行态加载失败') } finally { secondaryLoading.value = false } }
async function loadEvents(): Promise<void> { secondaryLoading.value = true; try { const response = await promptAuditAPI.listEvents(appliedFilters.value, page.value, pageSize.value); events.value = response.items || []; total.value = response.total || 0; selected.value = [] } catch (caught) { app.showError((caught as { message?: string }).message || '审计事件加载失败') } finally { secondaryLoading.value = false } }
function applyFilters(): void { appliedFilters.value = cloneData(filters.value); page.value = 1; deletePreview.value = null; void loadEvents() }
function resetFilters(): void { filters.value = emptyEventFilters(); appliedFilters.value = emptyEventFilters(); page.value = 1; deletePreview.value = null; void loadEvents() }
function toggleAll(): void { selected.value = selectedAll.value ? [] : events.value.map((item) => item.id) }
function toggleSelected(id: number): void { selected.value = selected.value.includes(id) ? selected.value.filter((item) => item !== id) : [...selected.value, id] }

async function openDetail(id: number): Promise<void> { detailOpen.value = true; detail.value = null; try { detail.value = await promptAuditAPI.getEvent(id) } catch (caught) { app.showError((caught as { message?: string }).message || '事件详情加载失败'); detailOpen.value = false } }
async function deleteIDs(ids: number[]): Promise<void> { if (!ids.length || !await confirm.ask({ title: ids.length === 1 ? '删除审计事件' : '批量删除审计事件', message: `将删除 ${ids.length} 条事件及其关联任务记录，操作不可撤销。`, confirmText: '确认删除', tone: ConfirmTone.DANGER })) return; deleting.value = true; try { const result = ids.length === 1 ? await promptAuditAPI.deleteEvent(ids[0]) : await promptAuditAPI.batchDeleteEvents(ids); app.showSuccess(`已删除 ${result.deleted_events} 条事件`); await Promise.all([loadEvents(), loadRuntime()]) } catch (caught) { app.showError((caught as { message?: string }).message || '事件删除失败') } finally { deleting.value = false } }

function addEndpoint(): void { if (!draft.value) return; draft.value.endpoints.push(createDefaultEndpoint(draft.value.endpoints.length + 1)) }
async function removeEndpoint(index: number): Promise<void> { if (!draft.value || !await confirm.ask({ title: '移除审核端点', message: `确认移除“${draft.value.endpoints[index]?.name}”？保存前可通过重置撤销。`, confirmText: '移除', tone: ConfirmTone.DANGER })) return; draft.value.endpoints.splice(index, 1) }
function toggleScanner(id: string): void { if (!draft.value) return; draft.value.scanners = draft.value.scanners.includes(id) ? draft.value.scanners.filter((item) => item !== id) : [...draft.value.scanners, id] }
function toggleGroup(id: number): void { if (!draft.value) return; draft.value.group_ids = draft.value.group_ids.includes(id) ? draft.value.group_ids.filter((item) => item !== id) : [...draft.value.group_ids, id] }
async function toggleBlocking(): Promise<void> { if (!draft.value) return; if (!draft.value.blocking_enabled) { if (!await confirm.ask({ title: '启用阻断模式', message: '阻断模式会把高风险判断直接作用于在线请求。请先确认端点探测和策略范围正确。', confirmText: '启用阻断', tone: ConfirmTone.DANGER })) return } draft.value.blocking_enabled = !draft.value.blocking_enabled }
async function probe(endpoint: PromptAuditEndpointDraft): Promise<void> { if (probingIds.value.includes(endpoint.id)) return; probingIds.value.push(endpoint.id); try { const result = await promptAuditAPI.probeEndpoint(endpoint); probeResults.value = { ...probeResults.value, [endpoint.id]: result }; if (result.ok) app.showSuccess(`${endpoint.name} 探测成功`); else app.showError(`${result.error_code || result.status}: ${result.message}`) } catch (caught) { app.showError((caught as { message?: string }).message || '端点探测失败') } finally { probingIds.value = probingIds.value.filter((id) => id !== endpoint.id) } }
function resetDraft(): void { if (serverDraft.value) draft.value = cloneData(serverDraft.value) }
async function saveConfig(): Promise<void> { if (!draft.value || !dirty.value) return; if (!draft.value.endpoints.length && draft.value.enabled) { app.showError('启用审计时至少需要一个端点'); return } saving.value = true; try { const saved = await promptAuditAPI.updateConfig(buildUpdateRequest(draft.value)); serverDraft.value = configToDraft(saved); draft.value = configToDraft(saved); app.showSuccess('提示词审计配置已保存'); await loadRuntime() } catch (caught) { app.showError((caught as { message?: string }).message || '配置保存失败，若版本冲突请重载后重试') } finally { saving.value = false } }

function resolvedDeleteFilters(): PromptEventFilters { return resolveDeleteRangeFilters(filters.value, deleteRange.value, Date.now()) }
async function previewFilterDelete(): Promise<void> { secondaryLoading.value = true; try { const resolved = resolvedDeleteFilters(); deletePreview.value = await promptAuditAPI.previewDelete(resolved); deletePreviewFilters.value = cloneData(resolved) } catch (caught) { app.showError((caught as { message?: string }).message || '删除预览失败') } finally { secondaryLoading.value = false } }
async function confirmFilterDelete(): Promise<void> { if (!deletePreview.value || !deletePreviewFilters.value) { await previewFilterDelete(); if (!deletePreview.value || !deletePreviewFilters.value) return } if (!await confirm.ask({ title: '按筛选删除审计事件', message: `快照匹配 ${deletePreview.value.matched_count} 条事件。确认令牌具有时效，删除后不可恢复。`, confirmText: `删除 ${deletePreview.value.matched_count} 条`, tone: ConfirmTone.DANGER })) return; deleting.value = true; try { const result = await promptAuditAPI.deleteEventsByFilter(deletePreviewFilters.value, deletePreview.value); deleteByFilterOpen.value = false; deletePreview.value = null; app.showSuccess(`已删除 ${result.deleted_events} 条事件`); await Promise.all([loadEvents(), loadRuntime()]) } catch (caught) { deletePreview.value = null; app.showError((caught as { message?: string }).message || '确认令牌失效，请重新预览') } finally { deleting.value = false } }

onMounted(loadInitial)
</script>

<template>
  <ConsoleShell>
    <main class="resource-page">
      <header class="resource-page__heading"><div><span class="resource-eyebrow">Prompt Governance</span><h1>提示词审计</h1><p>事件检索、证据详情、批量清理、运行状态、扫描策略与 Guard 端点池形成同一个可追溯工作区。</p></div><div v-if="draft" class="resource-toolbar__actions"><span class="resource-status">配置 v{{ draft.config_version }}</span><button class="resource-button resource-button--secondary" @click="loadRuntime">刷新运行态</button></div></header>
      <nav class="resource-tabs"><button :aria-selected="activeTab === PromptAuditTab.EVENTS" @click="activeTab = PromptAuditTab.EVENTS">审计事件</button><button :aria-selected="activeTab === PromptAuditTab.CONFIG" @click="activeTab = PromptAuditTab.CONFIG">运行与策略</button></nav>
      <PageState :loading="loading" :error="error" @retry="loadInitial"><template v-if="draft && runtime">
        <template v-if="activeTab === PromptAuditTab.EVENTS"><p v-if="draft.enabled && !draft.store_pass_events" class="notice notice--error">当前未保存通过事件，事件列表仅含风险/异常结果。可在“运行与策略”中开启。</p><section class="governance-card"><header class="governance-card__header"><div><h2>服务端筛选</h2><p>筛选同时作为按条件清理的预览基线。</p></div><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" @click="resetFilters">重置</button><button class="resource-button" @click="applyFilters">查询</button></div></header><div class="resource-form-grid resource-form-grid--4"><label>判断<select v-model="filters.decision"><option value="">全部</option><option value="pass">pass</option><option value="flag">flag</option><option value="critical">critical</option></select></label><label>风险级别<select v-model="filters.risk_level"><option value="">全部</option><option value="low">low</option><option value="medium">medium</option><option value="high">high</option><option value="critical">critical</option></select></label><label>端点 ID<input v-model="filters.endpoint" /></label><label>分组 ID<input v-model="filters.group_id" /></label><label>用户 ID<input v-model="filters.user_id" /></label><label>Key ID<input v-model="filters.api_key_id" /></label><label>请求 ID<input v-model="filters.request_id" /></label><label>Prompt 哈希<input v-model="filters.prompt_hash" /></label><label>关键词<input v-model="filters.keyword" /></label><label>开始时间<input v-model="filters.start_at" type="datetime-local" /></label><label>结束时间<input v-model="filters.end_at" type="datetime-local" /></label></div></section><div class="resource-toolbar"><div class="resource-toolbar__filters"><label class="resource-check"><input type="checkbox" :checked="selectedAll" @change="toggleAll" />全选当前页</label><span>已选 {{ selected.length }} 条</span></div><div class="resource-toolbar__actions"><button class="resource-button resource-button--secondary" :disabled="!selected.length || deleting" @click="deleteIDs(selected)">批量删除</button><button class="resource-button resource-button--danger" @click="deletePreview = null; deleteByFilterOpen = true">按条件清理</button></div></div><div v-if="secondaryLoading" class="page-state">正在加载事件…</div><div v-else-if="!events.length" class="resource-empty-inline">当前筛选范围没有审计事件。</div><div v-else class="resource-table"><table><thead><tr><th></th><th>时间 / 请求</th><th>用户 / Key</th><th>模型 / 端点</th><th>判断</th><th>分类</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="item in events" :key="item.id"><td><input type="checkbox" :checked="selected.includes(item.id)" :aria-label="`选择事件 ${item.id}`" @change="toggleSelected(item.id)" /></td><td>{{ formatGovernanceDate(item.created_at) }}<small><code>{{ item.snapshot.request_id }}</code></small></td><td>{{ item.snapshot.username || item.snapshot.user_email }}<small>U{{ item.snapshot.user_id }} · {{ item.snapshot.api_key_name }} · K{{ item.snapshot.api_key_id }}</small></td><td>{{ item.snapshot.model }}<small>{{ item.guard_endpoint_id }} · {{ item.scanner_backend }}</small></td><td><span :class="['resource-status', item.decision === 'pass' ? 'resource-status--active' : 'resource-status--error']">{{ item.decision }} · {{ item.risk_level }}</span><small>{{ item.action }}</small></td><td>{{ item.categories.join('、') || '—' }}<small>{{ item.matched_scanners.join('、') }}</small></td><td>{{ formatDuration(item.latency_ms) }}</td><td><div class="resource-inline-actions"><button class="resource-link" @click="openDetail(item.id)">详情</button><button class="resource-link resource-link--danger" @click="deleteIDs([item.id])">删除</button></div></td></tr></tbody></table></div><footer class="resource-pagination"><span>共 {{ total }} 条 · 第 {{ page }} / {{ pages }} 页</span><div class="resource-pagination__actions"><select v-model.number="pageSize" @change="page = 1; loadEvents()"><option :value="20">20 / 页</option><option :value="50">50 / 页</option></select><button class="resource-button resource-button--secondary" :disabled="page <= 1" @click="page--; loadEvents()">上一页</button><button class="resource-button resource-button--secondary" :disabled="page >= pages" @click="page++; loadEvents()">下一页</button></div></footer></template>

        <template v-else><section class="governance-kpis"><div><span>进程状态</span><strong>{{ runtime.process_status }}</strong></div><div><span>生效模式</span><strong>{{ runtime.effective_mode }}</strong></div><div><span>Worker</span><strong>{{ runtime.worker_active }} / {{ runtime.worker_total }}</strong></div><div><span>队列活跃 / 容量</span><strong>{{ runtime.queue.active }} / {{ runtime.queue_capacity }}</strong></div><div><span>处理 / 失败</span><strong>{{ formatCompactNumber(runtime.processed_total) }} / {{ formatCompactNumber(runtime.failed_total) }}</strong></div><div><span>入队 / 丢弃</span><strong>{{ formatCompactNumber(runtime.enqueued_total) }} / {{ formatCompactNumber(runtime.dropped_total) }}</strong></div><div><span>Guard 放行 / 拦截</span><strong>{{ runtime.guard_metrics.allowed }} / {{ runtime.guard_metrics.blocked }}</strong></div><div><span>Guard P95</span><strong>{{ formatDuration(runtime.guard_metrics.latency_p95_ms) }}</strong></div></section><p v-if="runtime.expected_config_version !== runtime.active_config_version" class="notice notice--error">配置版本尚未同步：期望 v{{ runtime.expected_config_version }}，运行中 v{{ runtime.active_config_version }}。请检查 {{ runtime.config_load_error || 'Worker 心跳' }}。</p><section class="governance-grid"><article class="governance-card"><header class="governance-card__header"><div><h2>运行依赖</h2><p>数据库、Redis、Worker 心跳和队列分层。</p></div></header><dl class="governance-detail"><dt>数据库</dt><dd>{{ runtime.database_status }}</dd><dt>Redis</dt><dd>{{ runtime.redis_status }}</dd><dt>Worker 心跳</dt><dd>{{ formatGovernanceDate(runtime.worker_heartbeat_at) }}</dd><dt>最近处理</dt><dd>{{ formatGovernanceDate(runtime.last_processed_at) }}</dd><dt>队列</dt><dd>staging {{ runtime.queue.staging }} · queued {{ runtime.queue.queued }} · processing {{ runtime.queue.processing }} · retry {{ runtime.queue.retry }} · failed {{ runtime.queue.failed }}</dd><dt>最近错误</dt><dd>{{ runtime.last_error_code || '—' }} · {{ runtime.last_error_message || '—' }}</dd></dl></article><article class="governance-card"><header class="governance-card__header"><div><h2>端点运行状态</h2><p>最近探测结果来自活跃配置。</p></div></header><div class="governance-list"><article v-for="(value, id) in runtime.endpoints" :key="id"><div><strong>{{ id }}</strong><small>{{ value.message }} · HTTP {{ value.http_status || '—' }}</small></div><div><span :class="['resource-status', value.ok ? 'resource-status--active' : 'resource-status--error']">{{ value.status }}</span><small>{{ formatDuration(value.latency_ms) }}</small></div></article></div></article></section><article class="governance-card"><header class="governance-card__header"><div><h2>Guard 端点池</h2><p>优先级策略按列表顺序故障转移；Token 留空表示保留已配置值。</p></div><button class="resource-button" @click="addEndpoint">添加端点</button></header><div v-for="(endpoint, index) in draft.endpoints" :key="endpoint.id" class="prompt-endpoint"><div class="resource-form-grid resource-form-grid--4"><label>ID<input v-model="endpoint.id" /></label><label>名称<input v-model="endpoint.name" /></label><label>API 地址<input v-model="endpoint.base_url" type="url" /></label><label>模型<input v-model="endpoint.model" /></label><label>Token<input v-model="endpoint.token" type="password" :placeholder="endpoint.has_token ? '已配置，留空保留' : '未配置'" /></label><label>超时 ms<input v-model.number="endpoint.timeout_ms" type="number" min="100" /></label><label>输入上限<input v-model.number="endpoint.input_limit" type="number" min="1" /></label><label class="resource-check"><input v-model="endpoint.enabled" type="checkbox" />启用</label><label class="resource-check"><input v-model="endpoint.clear_token" type="checkbox" />清除 Token</label></div><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" :disabled="probingIds.includes(endpoint.id)" @click="probe(endpoint)">{{ probingIds.includes(endpoint.id) ? '探测中…' : '探测端点' }}</button><button class="resource-button resource-button--danger" @click="removeEndpoint(index)">移除</button><span v-if="probeResults[endpoint.id]" :class="['resource-status', probeResults[endpoint.id].ok ? 'resource-status--active' : 'resource-status--error']">{{ probeResults[endpoint.id].message }} · {{ formatDuration(probeResults[endpoint.id].latency_ms) }}</span></div></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>策略与范围</h2><p>扫描器、分组、Worker 与保存策略。</p></div></header><div class="resource-form-grid resource-form-grid--4"><label class="resource-check"><input v-model="draft.enabled" type="checkbox" />启用审计</label><label class="resource-check"><input :checked="draft.blocking_enabled" type="checkbox" :disabled="!draft.enabled" @change="toggleBlocking" />阻断模式</label><label class="resource-check"><input v-model="draft.blocking_latest_turn_only" type="checkbox" :disabled="!draft.enabled || !draft.blocking_enabled" />仅检查最新轮</label><label class="resource-check"><input v-model="draft.store_pass_events" type="checkbox" />保存通过事件</label><label>Worker 数<input v-model.number="draft.worker_count" type="number" min="1" /></label><label>队列容量<input v-model.number="draft.queue_capacity" type="number" min="1" /></label><label class="resource-check"><input v-model="draft.all_groups" type="checkbox" />所有分组</label></div><h3>扫描器</h3><div class="governance-chip-list"><button v-for="scanner in SCANNER_CATALOG" :key="scanner.id" type="button" :class="['governance-chip', draft.scanners.includes(scanner.id) && 'governance-chip--active']" @click="toggleScanner(scanner.id)">{{ scanner.label }}</button></div><template v-if="!draft.all_groups"><h3>适用分组</h3><div class="governance-chip-list"><button v-for="group in groups" :key="group.id" type="button" :class="['governance-chip', draft.group_ids.includes(group.id) && 'governance-chip--active']" @click="toggleGroup(group.id)">{{ group.name }} · {{ group.platform }}</button></div></template></article><div class="governance-sticky-actions"><span :class="dirty ? 'notice notice--error' : 'muted'">{{ dirty ? '有未保存配置' : `已与服务端 v${draft.config_version} 同步` }}</span><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" :disabled="!dirty || saving" @click="resetDraft">重置</button><button class="resource-button" :disabled="!dirty || saving" @click="saveConfig">{{ saving ? '保存中…' : '保存配置' }}</button></div></div></template>
      </template></PageState>
    </main>

    <SurfaceDialog :show="detailOpen" title="提示词审计事件" description="快照、判断依据、扫描器证据与策略版本完整展示。" :width="DialogWidth.WIDE" @close="detailOpen = false"><div v-if="!detail" class="page-state">加载事件详情…</div><template v-else><dl class="governance-detail"><dt>请求</dt><dd><code>{{ detail.snapshot.request_id }}</code></dd><dt>用户 / Key</dt><dd>{{ detail.snapshot.username }} / {{ detail.snapshot.api_key_name }}</dd><dt>分组 / 模型</dt><dd>{{ detail.snapshot.group_name }} / {{ detail.snapshot.model }}</dd><dt>判断</dt><dd>{{ detail.decision }} · {{ detail.risk_level }} · {{ detail.action }}</dd><dt>扫描器</dt><dd>{{ detail.matched_scanners.join('、') || '—' }}</dd><dt>后端 / 版本</dt><dd>{{ detail.scanner_backend }} / {{ detail.scanner_version }}</dd><dt>策略 / 配置</dt><dd>{{ detail.policy_id }} v{{ detail.policy_version }} / config v{{ detail.config_version }}</dd><dt>Prompt 哈希</dt><dd><code>{{ detail.snapshot.prompt_hash }}</code></dd><dt>脱敏预览</dt><dd>{{ detail.snapshot.redacted_preview }}</dd><dt>完整 Prompt</dt><dd><pre class="resource-code">{{ detail.snapshot.full_prompt }}</pre></dd></dl><h3>问题摘要</h3><div class="governance-list"><article v-for="(issue, index) in detail.issue_summaries" :key="`${issue.code}-${index}`"><div><strong>{{ issue.title }} · {{ issue.severity_label }}</strong><small>{{ issue.description }} · {{ issue.action_label }}</small><pre class="resource-code">{{ issue.evidence }}</pre></div><strong>{{ issue.score }}</strong></article></div><h3>扫描器分数 / 证据</h3><pre class="resource-code">{{ JSON.stringify({ scores: detail.scanner_scores, evidence: detail.scanner_evidence }, null, 2) }}</pre></template></SurfaceDialog>
    <SurfaceDialog :show="deleteByFilterOpen" title="按条件清理事件" description="必须先生成后端快照与一次性确认令牌，再执行删除。" :width="DialogWidth.STANDARD" @close="deleteByFilterOpen = false"><div class="resource-form-stack"><label>删除时间范围<select v-model="deleteRange" @change="deletePreview = null"><option :value="PromptDeleteRange.ONE_DAY">1 天以前</option><option :value="PromptDeleteRange.SEVEN_DAYS">7 天以前</option><option :value="PromptDeleteRange.THIRTY_DAYS">30 天以前</option><option :value="PromptDeleteRange.NINETY_DAYS">90 天以前</option><option :value="PromptDeleteRange.ALL">全部历史</option><option :value="PromptDeleteRange.CUSTOM">使用当前起止时间</option></select></label><pre class="resource-code">{{ JSON.stringify(resolvedDeleteFilters(), null, 2) }}</pre><button class="resource-button resource-button--secondary" :disabled="secondaryLoading" @click="previewFilterDelete">{{ secondaryLoading ? '预览中…' : '生成删除预览' }}</button><div v-if="deletePreview" class="governance-danger-zone"><h3>匹配 {{ deletePreview.matched_count }} 条事件</h3><p class="governance-field-note">快照上限 #{{ deletePreview.snapshot_max_id }} · 令牌到期 {{ formatGovernanceDate(deletePreview.expires_at) }}</p><pre class="resource-code">{{ JSON.stringify(deletePreview.filter_summary, null, 2) }}</pre></div></div><template #footer><button class="button button--secondary" @click="deleteByFilterOpen = false">取消</button><button class="button resource-button--danger" :disabled="deleting || !deletePreview" @click="confirmFilterDelete">{{ deleting ? '删除中…' : '确认删除匹配事件' }}</button></template></SurfaceDialog>
  </ConsoleShell>
</template>

